export async function subscribeResource(uri) {
  if (typeof uri !== 'string' || uri.trim() === '') {
    throw new Error('URI is required and must be a non-empty string');
  }
  if (subscriptions.has(uri)) {
    throw new Error('Already subscribed to resource: ' + uri);
  }
  subscriptions.add(uri);
  return { subscribed: true, uri };
}

export async function unsubscribeResource(uri) {
  if (typeof uri !== 'string' || uri.trim() === '') {
    throw new Error('URI is required and must be a non-empty string');
  }
  if (!subscriptions.has(uri)) {
    throw new Error('Not subscribed to resource: ' + uri);
  }
  subscriptions.delete(uri);
  return { unsubscribed: true, uri };
}

export async function listTools() {
  return [
    {
      name: 'subscribeResource',
      description: 'Subscribe to a resource URI for change notifications.',
      inputSchema: {
        type: 'object',
        properties: {
          uri: { type: 'string', description: 'The non-empty resource URI to subscribe to.' }
        },
        required: ['uri'],
        additionalProperties: false
      }
    },
    {
      name: 'unsubscribeResource',
      description: 'Unsubscribe from a previously subscribed resource URI.',
      inputSchema: {
        type: 'object',
        properties: {
          uri: { type: 'string', description: 'The resource URI to unsubscribe from.' }
        },
        required: ['uri'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'subscribeResource':
      return await subscribeResource(args.uri);
    case 'unsubscribeResource':
      return await unsubscribeResource(args.uri);
    default:
      throw new Error('Unknown tool: ' + name);
  }
}

